import { adminSupabase } from "@/app/_lib/supabase/admin";
import { DEMO_EMAIL } from "@/app/_lib/demo";
import { activeUserIds } from "@/app/_lib/entitlement";
import { planPass, summarisePass, type PassAction } from "@/app/_lib/pass";
import { buildDraft } from "@/app/_lib/draft";
import { requiresApproval } from "@/app/_lib/recovery-mode";
import { UNDO_WINDOW_SECONDS } from "@/app/_lib/undo-window";
import { getFailures, getLadder, getVoice } from "@/app/_lib/db/reads";
import type { Failure, Ladder } from "@/app/_lib/types";

export interface PassResult {
  users: number;
  staged: number;
  stopped: number;
  scheduled: number;
  exhausted: number;
  skipped: string[];
  /** Owners with open failures and no active plan. Counted, not silent: an unentitled owner is
   *  a fact about the account, and a pass that reports `users: 0` with no reason is a pass
   *  nobody can tell apart from a broken one. */
  unentitled: number;
}

/** Owner ids with at least one open failure. The pass has nothing to do for anyone else, and
 *  scanning every user in the project to find that out is a table scan per night. */
async function ownersWithOpenFailures(): Promise<string[]> {
  const { data } = await adminSupabase()
    .from("cardchase_failures")
    .select("user_id")
    .eq("state", "open")
    .limit(5000);
  return [...new Set((data ?? []).map((r) => r.user_id as string))];
}

/** The demo user's id, resolved once. Returns null when the account does not exist yet, which
 *  is the correct answer on a fresh project — not a reason to skip everyone. */
async function demoUserId(): Promise<string | null> {
  const { data, error } = await adminSupabase().auth.admin.listUsers({ page: 1, perPage: 200 });
  // Failing to resolve the protected demo identity must stop the pass. Treating an admin API
  // failure as "no demo account" would put the fabricated book through the live recovery rail.
  if (error) throw new Error(`Unable to resolve the demo account: ${error.message}`);
  return data?.users.find((u) => u.email === DEMO_EMAIL)?.id ?? null;
}

async function applyAction(
  userId: string,
  action: PassAction,
  ctx: { failures: Failure[]; ladder: Ladder; voice: Awaited<ReturnType<typeof getVoice>>; now: number },
): Promise<void> {
  const db = adminSupabase();
  const failure = ctx.failures.find((f) => f.id === action.failureId);
  if (!failure) return;
  const nowIso = new Date(ctx.now).toISOString();

  if (action.kind === "stop") {
    // Terminal. The staged artifacts go with it — this is the case where undo is not enough
    // on its own, because the owner would otherwise have to remember to cancel a note attached
    // to a card the network just refused permanently.
    await db
      .from("cardchase_failures")
      .update({ state: action.state, stopped_reason: action.reason, next_retry_at: null, updated_at: nowIso })
      .eq("id", failure.id)
      .eq("user_id", userId);
    for (const table of ["cardchase_retries", "cardchase_messages"] as const) {
      await db
        .from(table)
        .update({ status: "cancelled", blocked_reason: action.reason })
        .eq("failure_id", failure.id)
        .eq("user_id", userId)
        .in("status", ["queued", "draft"]);
    }
    await db.from("cardchase_events").insert({
      user_id: userId,
      failure_id: failure.id,
      kind: action.reason === "retry_cap" ? "capped" : "blocked",
      title:
        action.reason === "retry_cap"
          ? `Reached the retry cap for ${failure.customer_name ?? "a customer"}`
          : `Stopped retrying ${failure.customer_name ?? "a customer"}`,
      detail: action.explanation,
      evidence: [
        { kind: "decline_code", label: failure.decline_code ?? "none" },
        { kind: "network_advice_code", label: failure.network_advice_code ?? "none" },
        { kind: "network_decline_code", label: failure.network_decline_code ?? "none" },
        { kind: "authority", label: action.authority },
      ],
      created_at: nowIso,
    });
    return;
  }

  if (action.kind === "schedule") {
    if (failure.next_retry_at === action.dueAt) return; // already says so; not a write
    await db
      .from("cardchase_failures")
      .update({ next_retry_at: action.dueAt, updated_at: nowIso })
      .eq("id", failure.id)
      .eq("user_id", userId);
    return;
  }

  if (action.kind === "exhausted") {
    await db
      .from("cardchase_failures")
      .update({ state: "churned", stopped_reason: "ladder_exhausted", next_retry_at: null, updated_at: nowIso })
      .eq("id", failure.id)
      .eq("user_id", userId);
    await db.from("cardchase_events").insert({
      user_id: userId,
      failure_id: failure.id,
      kind: "capped",
      title: `Ran out of ladder for ${failure.customer_name ?? "a customer"}`,
      detail: `All ${action.rungsRun} rungs run and the charge never cleared. No further attempt will be made.`,
      evidence: [{ kind: "rungs", label: String(action.rungsRun) }],
      created_at: nowIso,
    });
    return;
  }

  // ── stage ────────────────────────────────────────────────────────────────────
  // Approving is what STARTS the window, so an artifact that needs a human tap is staged with
  // no approved_at and no countdown running. Autopilot stamps both now.
  const needsApproval = action.needsApproval;
  const approvedAt = needsApproval ? null : nowIso;
  const releaseAt = needsApproval ? null : action.releaseAt;

  if (action.retry) {
    await db.from("cardchase_retries").insert({
      user_id: userId,
      failure_id: failure.id,
      rung: action.rungIndex,
      status: "queued",
      scheduled_for: nowIso,
      approved_at: approvedAt,
      release_at: releaseAt,
      amount_cents: failure.amount_cents,
      created_at: nowIso,
    });
  }

  if (action.message && !failure.do_not_contact) {
    const draft = buildDraft({
      failure: {
        amount_cents: failure.amount_cents,
        currency: failure.currency,
        card_brand: failure.card_brand,
        card_last4: failure.card_last4,
        decline_code: failure.decline_code,
      },
      customerName: failure.customer_name ?? "there",
      rung: action.rung,
      voice: ctx.voice,
      updateUrl: null,
    });
    await db.from("cardchase_messages").insert({
      user_id: userId,
      failure_id: failure.id,
      rung: action.rungIndex,
      channel: action.rung.channel,
      subject: draft.subject,
      body: draft.body,
      tone: draft.tone,
      status: needsApproval ? "draft" : "queued",
      approved_at: approvedAt,
      release_at: releaseAt,
      scheduled_for: nowIso,
      created_at: nowIso,
    });
  }

  // The failure has climbed a rung whether or not a human taps it: the ladder is a schedule,
  // and a rung that came due has come due. The cap counts RETRIES, and a retry is only counted
  // when it is actually attempted — that happens in the dispatcher, not here.
  await db
    .from("cardchase_failures")
    .update({ rung: action.rungIndex + 1, next_retry_at: null, updated_at: nowIso })
    .eq("id", failure.id)
    .eq("user_id", userId);

  await db.from("cardchase_events").insert({
    user_id: userId,
    failure_id: failure.id,
    kind: "drafted",
    title: `Prepared rung ${action.rungIndex + 1} for ${failure.customer_name ?? "a customer"}`,
    detail: needsApproval
      ? [action.retry ? "a retry" : null, action.message ? "a note" : null].filter(Boolean).join(" and ") +
        ", waiting for your approval."
      : `Firing automatically — ${UNDO_WINDOW_SECONDS}s to take it back.`,
    evidence: [
      { kind: "rung", label: String(action.rungIndex + 1) },
      { kind: "kill_window", label: `${UNDO_WINDOW_SECONDS}s` },
    ],
    created_at: nowIso,
  });
}

/**
 * Run the pass for every owner with an open failure.
 *
 * `now` is injectable so a test owns the clock, exactly as the planner's is.
 */
export async function runPass({ now = Date.now() }: { now?: number } = {}): Promise<PassResult> {
  const db = adminSupabase();
  const demo = await demoUserId();
  const owners = await ownersWithOpenFailures();
  const result: PassResult = { users: 0, staged: 0, stopped: 0, scheduled: 0, exhausted: 0, skipped: [], unentitled: 0 };

  /* ⛔ THE PASS IS THE PRODUCT AND IT RAN FOR EVERYONE. "Retries on the ladder you set" and
   * "Notes drafted in your voice" are PRO's two headline rows, and before 2026-09-01 this loop
   * staged both for every owner with an open failure — no subscription check anywhere in the
   * repo. One query for the whole batch, not one per owner: a nightly pass over N owners should
   * not be N extra round trips to learn who is allowed. */
  const entitled = await activeUserIds(owners.filter((id) => id !== demo));

  for (const userId of owners) {
    if (demo && userId === demo) {
      result.skipped.push("demo");
      continue;
    }
    if (!entitled.has(userId)) {
      result.unentitled += 1;
      continue;
    }
    const [failures, ladder, voice] = await Promise.all([getFailures(userId), getLadder(userId), getVoice(userId)]);
    /* ⛔ THE LADDER GOES TO THE PLANNER UNTOUCHED, AND AUTOPILOT IS NOT A TIER QUESTION.
     * For a few hours today this forced `recovery_mode: "copilot"` on anyone below SCALE. SCALE
     * was removed the same day — its multi-account claims describe a model this repo does not
     * have — and with it that gate, which would have inverted the moment PRO became the last
     * rung. Autopilot is EARNED and always was: recovery-mode.ts unlocks it on
     * CLEAN_APPROVALS_NEEDED clean approvals, the approve route counts them and the undo route
     * takes them back. PRO's pricing card says exactly that. Nothing here second-guesses it. */
    const actions = planPass({ now, failures, ladder });
    for (const action of actions) {
      await applyAction(userId, action, { failures, ladder, voice, now });
    }
    const s = summarisePass(actions);
    result.users += 1;
    result.staged += s.staged;
    result.stopped += s.stopped;
    result.scheduled += s.scheduled;
    result.exhausted += s.exhausted;

    await db
      .from("cardchase_ladder")
      .upsert({ user_id: userId, last_pass_at: new Date(now).toISOString() }, { onConflict: "user_id" });
  }

  return result;
}

